        // Assert
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_NonExistentId_ReturnsNull()
    {
        var result = _service.GetOrder("does-not-exist");

        Assert.IsNull(result);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_MultipleOrders_ReturnsAll()
    {
        // Arrange
        var items = CreateItems(("A", 1m, 1));
        _service.CreateOrder("cust-A", items);
        _service.CreateOrder("cust-A", items);
        _service.CreateOrder("cust-B", items);

        // Act
        var result = _service.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.HasCount(2, result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_NoOrders_ReturnsEmptyList()
    {
        var result = _service.GetOrdersByCustomer("nobody");

        Assert.IsEmpty(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingCustomer()
    {
        // Arrange
        var items = CreateItems(("X", 10m, 1));
        var order = _service.CreateOrder("target", items);
        _service.CreateOrder("other", items);

        // Act
        var result = _service.GetOrdersByCustomer("target");

        // Assert
        var single = Assert.ContainsSingle(result);
        Assert.AreEqual(order.Id, single.Id);
    }

    #endregion
}

